            for k in range(len(bottoms)):
                sm[k]=np.median(bottoms[max(0,k-1):min(len(bottoms),k+2)])
        ground=float(np.percentile(sm,90))
        if not(0.55*H<=ground<=0.82*H): 
            if verbose: print(' skip ground',grp[0],grp[-1],ground)
            continue
        medh=float(np.median(heights))
        if medh < 0.12*H:
            if verbose: print(' skip medh',grp[0],grp[-1],medh)
            continue
        th=max(12.0,0.05*medh)
        lift=ground-sm
        runs=[];k=0
        while k<len(lift):
            if lift[k]>th:
                st=k
                while k<len(lift) and lift[k]>th:k+=1
                runs.append((st,k-1,lift[st:k]))
            else:k+=1
        for st,en,lv in runs:
            dur=en-st+1; peak=float(lv.max())
            if dur<3 or peak>0.45*H: continue
            take=grp[st]; land=None
            for k in range(en+1,len(lift)):
                if lift[k]<=th: land=grp[k];break
            if land is None:
                for j in idxs:
                    if j>grp[en]: land=j;break
            if land is None: continue
            score=peak*min(dur,20)
            cand=(score,peak,dur,take,land,grp[0],grp[-1],ground,th,len(grp))
            if verbose: print(' grp',grp[0],grp[-1],'ground',ground,'th',round(th,1),'run',grp[st],grp[en],'peak',peak,'dur',dur,'take',take,'land',land)
            if best is None or cand[0]>best[0]: best=cand
    return best
for pol in ('dark','bright'):
    print('POL',pol)
    b=eval2(filt(feats[pol]),True)
    print(' BEST',b)
