import sys

import cv2
import numpy as np


OUTPUT_PATH = "/app/output.toml"


def _components(mask, min_area):
    count, labels, stats, _ = cv2.connectedComponentsWithStats(mask, 8)
    components = []
    for label in range(1, count):
        area = int(stats[label, cv2.CC_STAT_AREA])
        if area >= min_area:
            x, y, w, h = [int(v) for v in stats[label, :4]]
            components.append((area, x, y, w, h, label))
    return labels, components


def _largest_cluster(labels, components, width, height):
    if not components:
        return []

    gap_x = 0.25 * width
    gap_y = 0.25 * height
    count = len(components)
    parent = list(range(count))

    def find(a):
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a

    def union(a, b):
        root_a = find(a)
        root_b = find(b)
        if root_a != root_b:
            parent[root_b] = root_a

    def box(index):
        _, x, y, w, h, _ = components[index]
        return x, y, x + w, y + h

    for i in range(count):
        x0, y0, x1, y1 = box(i)
        for j in range(i + 1, count):
            u0, v0, u1, v1 = box(j)
            dx = max(0, max(u0 - x1, x0 - u1))
            dy = max(0, max(v0 - y1, y0 - v1))
            if dx <= gap_x and dy <= gap_y:
                union(i, j)

    groups = {}
    for i in range(count):
        root = find(i)
        groups.setdefault(root, []).append(i)

    best = max(groups.values(), key=lambda g: sum(components[i][0] for i in g))
    return [components[i] for i in best]


def _extract_features(path):
    capture = cv2.VideoCapture(path)
    ok, background = capture.read()
    if not ok:
        raise RuntimeError("Unable to read the input video")

    height, width = background.shape[:2]
    background_gray = cv2.cvtColor(background, cv2.COLOR_BGR2GRAY).astype(np.int16)

    min_component_area = max(25, int(width * height * 0.00008))
    min_frame_area = max(150, int(width * height * 0.0015))
    threshold = 25
    features = {"dark": [], "bright": []}

    def record(frame, frame_number):
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY).astype(np.int16)
        for polarity, signed_difference in (
            ("dark", background_gray - gray),
            ("bright", gray - background_gray),
        ):
            mask = (signed_difference > threshold).astype(np.uint8)
            mask = cv2.morphologyEx(
                mask, cv2.MORPH_OPEN, np.ones((3, 3), np.uint8)
            )
            labels, components = _components(mask, min_component_area)
            cluster = _largest_cluster(labels, components, width, height)

            if not cluster:
                features[polarity].append(
                    (frame_number, None, None, None, None, 0)
                )
                continue

            x0 = min(component[1] for component in cluster)
            y0 = min(component[2] for component in cluster)
            x1 = max(component[1] + component[3] for component in cluster)
            y1 = max(component[2] + component[4] for component in cluster)
            area = sum(component[0] for component in cluster)

            if area < min_frame_area:
                features[polarity].append(
                    (frame_number, None, None, None, None, area)
                )
            else:
                features[polarity].append(
                    (frame_number, x0, y0, x1, y1, area)
                )

    record(background, 0)
    frame_number = 0
    while True:
        ok, frame = capture.read()
        if not ok:
            break
        frame_number += 1
        record(frame, frame_number)

    capture.release()
    return features, width, height


def _filter_features(features, width, height):
    min_frame_area = max(150, int(width * height * 0.0015))
    filtered = []
    for item in features:
        frame_number, x0, y0, x1, y1, area = item
        if x0 is None:
            filtered.append(item)
            continue

        w = x1 - x0
        h = y1 - y0
        if (
            area < min_frame_area
            or w > 0.85 * width
            or h > 0.9 * height
        ):
            filtered.append((frame_number, None, None, None, None, area))
        else:
            filtered.append(item)
    return filtered


def _find_event(features, width, height, strict=True):
    data = {item[0]: item for item in features if item[1] is not None}
    if not data:
        return None

    indices = sorted(data)
    groups = []
    current = [indices[0]]
    for index in indices[1:]:
        if index - current[-1] <= 4:
            current.append(index)
        else:
            groups.append(current)
            current = [index]
    groups.append(current)

    best = None
    for group in groups:
        if len(group) < 3:
            continue

        bottoms = np.array([data[i][4] for i in group], dtype=float)
        heights = np.array([data[i][4] - data[i][2] for i in group], dtype=float)
        smoothed = bottoms.copy()
        if len(bottoms) >= 3:
            for k in range(len(bottoms)):
                smoothed[k] = np.median(
                    bottoms[max(0, k - 1):min(len(bottoms), k + 2)]
                )

        ground = float(np.percentile(smoothed, 90))
        if strict and not (0.55 * height <= ground <= 0.82 * height):
            continue

        median_height = float(np.median(heights))
        if strict and median_height < 0.12 * height:
            continue

        lift_threshold = max(12.0, 0.05 * median_height)
        lift = ground - smoothed

        runs = []
        k = 0
        while k < len(lift):
            if lift[k] > lift_threshold:
                start = k
                while k < len(lift) and lift[k] > lift_threshold:
                    k += 1
                runs.append((start, k - 1, lift[start:k]))
            else:
                k += 1

        for start, end, values in runs:
            duration = end - start + 1
            peak = float(values.max())
            if strict:
                if duration < 3 or peak > 0.45 * height:
                    continue
            elif duration < 2:
                continue

            takeoff = group[start]
            landing = None
            for k in range(end + 1, len(lift)):
                if lift[k] <= lift_threshold:
                    landing = group[k]
                    break
            if landing is None:
                for index in indices:
                    if index > group[end]:
                        landing = index
                        break
            if landing is None:
                continue

            score = peak * min(duration, 20)
            candidate = (
                score,
                peak,
                duration,
                takeoff,
                landing,
                group[0],
                group[-1],
                ground,
                lift_threshold,
                len(group),
            )
            if best is None or candidate[0] > best[0]:
                best = candidate

    return best


def _analyze(path):
    features, width, height = _extract_features(path)

    best = None
    for polarity in ("dark", "bright"):
        filtered = _filter_features(features[polarity], width, height)
        candidate = _find_event(filtered, width, height, strict=True)
        if candidate is not None and (best is None or candidate[0] > best[0]):
            best = candidate

    if best is None:
        for polarity in ("dark", "bright"):
            candidate = _find_event(features[polarity], width, height, strict=False)
            if candidate is not None and (best is None or candidate[0] > best[0]):
                best = candidate

    if best is None:
        return 0, 0

    return int(best[3]), int(best[4])


def _write_output(takeoff, landing):
    with open(OUTPUT_PATH, "w", encoding="utf-8") as output:
        output.write(f"jump_takeoff_frame_number = {takeoff}\n")
        output.write(f"jump_land_frame_number = {landing}\n")


def main():
    video_path = sys.argv[1] if len(sys.argv) > 1 else "/app/example_video.mp4"
    takeoff, landing = _analyze(video_path)
    _write_output(takeoff, landing)


if __name__ == "__main__":
    main()
